BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — 501(h) expenditure test sliding scale computation
(3, 'Tax-Exempt Organizations', 'Riverdale Education Alliance, a 501(c)(3) public charity with $800,000 in exempt purpose expenditures, elects the Section 501(h) expenditure test. During 2026, it spends $160,000 on direct lobbying and $60,000 on grassroots lobbying. Evaluate whether the organization has exceeded its lobbying limits under Section 4911.', '["Both limits are exceeded — direct lobbying exceeds the $145,000 ceiling and grassroots lobbying exceeds the $36,250 ceiling, triggering a 25% excise tax on each excess amount", "Only the grassroots limit is exceeded — the overall lobbying ceiling is $160,000, which equals the direct lobbying amount, but grassroots exceeds its separate ceiling", "Neither limit is exceeded — the 501(h) election allows lobbying up to 20% of total expenditures ($160,000) and grassroots up to 50% of that amount ($80,000)", "Only the direct lobbying limit is exceeded — the grassroots ceiling is calculated as 50% of the overall lobbying limit, making it $72,500"]'::jsonb, 0, 'Under IRC Sections 501(h) and 4911, the lobbying ceiling uses a sliding scale: 20% of the first $500,000 plus 15% of the next $300,000 of exempt purpose expenditures equals $145,000. The grassroots ceiling is 25% of the lobbying limit ($36,250). Direct lobbying of $160,000 exceeds $145,000 and grassroots of $60,000 exceeds $36,250, so both ceilings are breached. Choice C incorrectly applies a flat 20% rate rather than the statutory sliding scale.', 'hard', 4),

-- Q2: medium / L3 — Controlled entity rental payments as UBIT
(3, 'Tax-Exempt Organizations', 'Hope Medical Research Institute, a 501(c)(3), owns 90% of MedTech Labs, a taxable C corporation. MedTech pays the institute $200,000 in annual rent for laboratory space, while comparable fair market rent is $140,000. How is this rental income treated for UBIT purposes?', '["The entire $200,000 is excluded from UBIT because all rents from real property are excluded under Section 512(b)(3)", "Only $140,000 is subject to UBIT because the controlled entity exception applies only to the fair market value portion", "The $60,000 excess over fair market value is subject to UBIT under the controlled entity rules of Section 512(b)(13)", "The entire $200,000 is subject to UBIT because the organization owns more than 50% of MedTech Labs"]'::jsonb, 2, 'Under IRC Section 512(b)(13), rents received from a controlled entity (80%+ ownership) are treated as UBIT to the extent they exceed fair market value. The $60,000 excess ($200,000 minus $140,000 FMV) is subject to UBIT while the remaining $140,000 retains the passive income exclusion under Section 512(b)(3). Choice D incorrectly treats the entire amount as UBIT rather than only the excess over FMV.', 'medium', 3),

-- Q3: medium / L2 — Supporting organization classification 509(a)(3)
(3, 'Tax-Exempt Organizations', 'Community Health Partners is organized exclusively to raise funds for and provide administrative support to City General Hospital, a 501(c)(3) public charity. It receives 85% of its revenue from private donors rather than public sources. Under what provision does it most likely qualify as a public charity?', '["Section 509(a)(1), because it receives substantial public support", "Section 509(a)(3), because it operates exclusively to support a public charity", "Section 509(a)(2), because its gross receipts are from activities related to exempt functions", "Section 509(a)(4), because it tests for public safety"]'::jsonb, 1, 'Under IRC Section 509(a)(3), an organization operated exclusively to support one or more public charities qualifies as a supporting organization and is classified as a public charity itself, regardless of its funding sources. Community Health Partners exists solely to support City General Hospital, meeting this test. Choice A is incorrect because the organization does not independently meet the one-third public support test under 509(a)(1).', 'medium', 2),

-- Q4: medium / L3 — Personal property rents exceeding 10% incidental threshold
(3, 'Tax-Exempt Organizations', 'Coastal Wildlife Preserve, a 501(c)(3), leases a building and heavy equipment to a film company under a single lease. Total annual rent is $100,000, of which $30,000 is attributable to personal property (equipment) and $70,000 to real property (building). The personal property portion is 30%, exceeding the 10% incidental threshold. Apply the UBIT rules.', '["The entire $100,000 is excluded because all rental income from leased property qualifies as passive income", "The entire $100,000 is subject to UBIT because any personal property component above 10% taints the entire lease", "Only the $70,000 real property rent is subject to UBIT while the $30,000 personal property rent is excluded", "Only the $30,000 personal property rent is subject to UBIT while the $70,000 real property rent remains excluded under Section 512(b)(3)"]'::jsonb, 3, 'Under IRC Section 512(b)(3), rents from real property are excluded from UBIT, but rents from personal property are included. When personal property rent exceeds the 10% incidental threshold, the personal property portion cannot be disregarded. The $30,000 personal property rent (30% of total) is subject to UBIT, while the $70,000 real property rent remains excluded. Choice B incorrectly treats the entire rent as UBIT; exceeding the threshold only affects the personal property portion.', 'medium', 3),

-- Q5: hard / L4 — Private inurement vs private benefit distinction
(3, 'Tax-Exempt Organizations', 'Bright Horizons Academy, a 501(c)(3), provides its founder''s daughter (a non-employee with no organizational role) free use of the organization''s vacation property valued at $15,000 annually. The founder is the board chair. The IRS examines this arrangement. Evaluate whether the private inurement doctrine, the private benefit doctrine, or both apply.', '["Only private inurement applies because the founder is an insider and the benefit flows through the founder''s family", "Only private benefit applies because the daughter is not an insider, so the inurement prohibition does not reach her directly", "Both doctrines apply — private inurement because the founder indirectly benefits as an insider, and private benefit because the daughter directly receives organizational resources", "Neither doctrine applies because providing incidental benefits to family members of board members is permissible if the value is below $25,000"]'::jsonb, 2, 'Under IRC Section 501(c)(3), private inurement prohibits net earnings from benefiting insiders — the founder indirectly benefits through family. The broader private benefit doctrine prohibits excessive benefits to any individual, insider or not — the daughter directly receives a $15,000 benefit. Both doctrines are implicated. Choice B is incorrect because the founder''s indirect benefit as board chair triggers the inurement prohibition even though the daughter herself is not an insider.', 'hard', 4),

-- Q6: medium / L2 — Form 990-N (e-Postcard) threshold
(3, 'Tax-Exempt Organizations', 'Pinewood Neighborhood Association, a small 501(c)(3), has gross receipts of $42,000 and total assets of $75,000 for the current tax year. Which annual information return must the organization file with the IRS?', '["Form 990-N (e-Postcard), because gross receipts are $50,000 or less", "Form 990-EZ, because gross receipts are between $25,000 and $100,000", "Form 990, because all 501(c)(3) organizations must file the full return regardless of size", "Form 990-PF, because small organizations are classified as private foundations"]'::jsonb, 0, 'Under IRC Section 6033, organizations with gross receipts normally $50,000 or less may file Form 990-N (e-Postcard), an electronic notice requiring only basic identifying information. Pinewood''s $42,000 in gross receipts falls below this threshold. Choice B is incorrect because Form 990-EZ applies when gross receipts are at least $50,000 but less than $200,000, and total assets are under $500,000.', 'medium', 2),

-- Q7: medium / L3 — Section 4945 lobbying by private foundation
(3, 'Tax-Exempt Organizations', 'Sterling Family Foundation, a private foundation, spends $25,000 to hire a lobbyist who contacts Congress to influence pending education legislation. The board approved the expenditure as consistent with its educational mission. Determine the tax consequences under Section 4945.', '["No tax applies because the expenditure furthers the foundation''s educational exempt purpose", "The $25,000 is a taxable expenditure subject to a 20% initial excise tax ($5,000) on the foundation and a potential 5% tax on any manager who approved it", "The expenditure is permitted because private foundations may lobby if spending does not exceed 5% of their annual budget", "The $25,000 is subject to the Section 4911 excise tax of 25% rather than Section 4945"]'::jsonb, 1, 'Under IRC Section 4945(d)(1), any amount paid by a private foundation to influence legislation is a taxable expenditure, regardless of whether it relates to the foundation''s exempt purpose. The initial excise tax is 20% on the foundation ($5,000) and 5% on any foundation manager who knowingly approved it. Choice A incorrectly assumes a mission-alignment exception exists; Section 4945 applies to all private foundation lobbying without exception.', 'medium', 3),

-- Q8: medium / L2 — Form 990 filing deadline and extension
(3, 'Tax-Exempt Organizations', 'Lakeside Community Center, a calendar-year 501(c)(3), needs to determine its filing deadline for the annual Form 990. What is the due date, and what extension is available?', '["March 15, with an automatic 6-month extension using Form 7004", "April 15, with an automatic 3-month extension using Form 2553", "June 15, with no extension available for tax-exempt organizations", "May 15, with an automatic 6-month extension available using Form 8868"]'::jsonb, 3, 'Under IRC Section 6033, Form 990 is due on the 15th day of the 5th month after the organization''s tax year ends. For calendar-year organizations, this is May 15. An automatic 6-month extension (to November 15) is available by filing Form 8868. Choice A is incorrect because March 15 is the deadline for partnership and S corporation returns, not exempt organization returns.', 'medium', 2),

-- Q9: medium / L3 — NOL carryforward for UBIT
(3, 'Tax-Exempt Organizations', 'Heritage Arts Council, a 501(c)(3), had unrelated business taxable losses of $20,000 in 2025 from a commercial printing shop. In 2026, it has $35,000 of gross unrelated business income and $8,000 in directly connected expenses from the same activity. After the $1,000 specific deduction, determine the 2026 unrelated business taxable income considering the NOL carryforward.', '["$35,000, because NOL carryforwards from prior years are not permitted for exempt organizations", "$26,000, because the NOL deduction does not apply and taxable income is $35,000 minus $8,000 minus $1,000", "$6,000, because the $20,000 NOL carryforward reduces the $26,000 pre-NOL taxable amount to $6,000", "$14,000, because only 50% of the NOL carryforward may be applied in any single year"]'::jsonb, 2, 'Under IRC Section 512(b)(6), exempt organizations may use NOL carryforwards computed solely from unrelated business income items. The 2026 UBTI before NOL is $35,000 minus $8,000 expenses minus $1,000 specific deduction, equaling $26,000. The $20,000 NOL from 2025 further reduces UBTI to $6,000. Choice B incorrectly omits the NOL carryforward, which is explicitly permitted under Section 512(b)(6).', 'medium', 3),

-- Q10: easy / L1 — Dissolution clause requirement
(3, 'Tax-Exempt Organizations', 'What is the dissolution clause required in a 501(c)(3) organization''s governing documents?', '["A provision requiring the organization to dissolve after 10 years of operation", "A provision directing that remaining assets be distributed to another exempt organization or government upon dissolution", "A provision allowing members to vote on dissolving the organization at any time", "A provision requiring all debts to be paid before the organization can be dissolved"]'::jsonb, 1, 'Under IRC Section 501(c)(3) and Reg. 1.501(c)(3)-1(b)(4), the organizational test requires governing documents to include a dissolution clause providing that upon dissolution, remaining assets will be distributed to another 501(c)(3) organization or to government for a public purpose. Choice A is incorrect — there is no mandatory dissolution timeline; the clause governs asset distribution upon dissolution, not organizational lifespan.', 'easy', 1),

-- Q11: easy / L1 — Churches, schools, hospitals automatic public charity
(3, 'Tax-Exempt Organizations', 'Under Section 509, which type of 501(c)(3) organization is automatically classified as a public charity regardless of its funding sources?', '["A private operating foundation that distributes all of its income annually", "A supporting organization described in Section 509(a)(3)", "Any organization with gross receipts under $50,000", "A church, school, or hospital"]'::jsonb, 3, 'Under IRC Section 509(a)(1) and Section 170(b)(1)(A), churches, schools, and hospitals are automatically classified as public charities without needing to meet the one-third public support test. This classification is based on the nature of the organization rather than its funding sources. Choice B describes another type of public charity, but supporting organizations must meet additional operational requirements under 509(a)(3).', 'easy', 1),

-- Q12: hard / L3 — Research exclusion from UBIT applied to university scenario
(3, 'Tax-Exempt Organizations', 'Midwestern State University, a 501(c)(3), operates a research laboratory with three revenue streams: NIH-funded cancer studies ($500,000), proprietary pharmaceutical testing under exclusive contract with a single drug manufacturer ($300,000), and basic science research with results published in peer-reviewed journals ($200,000). Apply the UBIT research exclusion to determine which revenue streams qualify.', '["The NIH-funded research ($500,000) and published basic science research ($200,000) are excluded, but the proprietary pharmaceutical testing ($300,000) is subject to UBIT", "All three revenue streams are excluded because all research conducted by a university is exempt from UBIT", "Only the NIH-funded research ($500,000) is excluded because it is the only government-funded project", "None of the revenue is excluded because operating a commercial research laboratory is a trade or business"]'::jsonb, 0, 'Under IRC Section 512(b)(8)-(9), research performed for the U.S. government or by a college/university is excluded from UBIT, as is research with results freely available to the public. The NIH studies qualify as government-funded and the published research qualifies as publicly available. The proprietary testing produces results exclusively for one company and does not qualify. Choice B incorrectly assumes all university research is excluded; proprietary contract research for a single private party is not.', 'hard', 3),

-- Q13: easy / L2 — Bingo exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Valley Community Church, a 501(c)(3), holds weekly bingo nights earning $18,000 annually. The state permits charitable bingo, and no commercial bingo operations exist in the surrounding area. Is the bingo income subject to UBIT?', '["Yes, because bingo is a trade or business regularly carried on that is unrelated to the church''s religious purpose", "Yes, because weekly bingo nights exceed the not-regularly-carried-on threshold", "No, because all income earned by churches is automatically exempt from UBIT", "No, because bingo qualifies for a statutory exclusion when it is legal under state law and commercial bingo is not ordinarily conducted in the area"]'::jsonb, 3, 'Under IRC Section 513(f), bingo games are excluded from UBIT if the game is lawful under state and local law and commercial bingo is not regularly carried on in the jurisdiction. Valley Community Church meets both conditions. Choice A incorrectly ignores the specific statutory exclusion for bingo, which overrides the general three-part UBIT test even when all three conditions are otherwise met.', 'easy', 2),

-- Q14: easy / L1 — Form 990-PF filing requirement for all private foundations
(3, 'Tax-Exempt Organizations', 'Which type of tax-exempt organization must file Form 990-PF regardless of its size or gross receipts?', '["All 501(c)(3) public charities", "Only private foundations with gross receipts exceeding $200,000", "All private foundations", "Only private foundations that have net investment income"]'::jsonb, 2, 'Under IRC Section 6033 and the Form 990-PF instructions, every private foundation must file Form 990-PF annually regardless of its size, gross receipts, or total assets. This differs from public charities, which file Form 990, 990-EZ, or 990-N based on size thresholds. Choice B is incorrect because there is no size threshold — even the smallest private foundation must file the full Form 990-PF.', 'easy', 1),

-- Q15: easy / L1 — Schedule B confidentiality
(3, 'Tax-Exempt Organizations', 'Which Form 990 schedule contains the list of contributors and is not available for public inspection?', '["Schedule A — Public Charity Status and Public Support", "Schedule J — Compensation Information", "Schedule D — Supplemental Financial Statements", "Schedule B — Schedule of Contributors"]'::jsonb, 3, 'Under IRC Section 6104(d)(3)(A), Schedule B (Schedule of Contributors) is the only major Form 990 schedule not available for public inspection. Donor names and addresses are confidential to protect contributor privacy. Choice A is incorrect because Schedule A, which reports public charity status and public support calculations, is publicly available along with the rest of Form 990.', 'easy', 1),

-- Q16: hard / L4 — Section 4942 correction period and additional tax
(3, 'Tax-Exempt Organizations', 'Westbrook Family Foundation, a private foundation, has non-charitable-use assets of $6,000,000 at year-end 2025. It distributes $180,000 for charitable purposes during 2025, falling short of the 5% minimum. The IRS issues a deficiency notice, but the foundation fails to make any corrective distributions within the taxable period. Evaluate the full sequence of tax consequences under Section 4942.', '["An initial 15% excise tax on the $120,000 shortfall with no additional penalty if corrected within two years", "A 30% initial excise tax on the $120,000 shortfall ($36,000), and since the shortfall was not corrected within the taxable period, a 100% additional tax on the remaining undistributed amount", "A 20% initial excise tax on the shortfall plus automatic revocation of exempt status if not corrected within 90 days", "A 10% initial excise tax on the $120,000 shortfall ($12,000) with a 200% additional tax if not corrected"]'::jsonb, 1, 'Under IRC Section 4942, the minimum distribution is 5% of non-charitable-use assets ($300,000). The $120,000 shortfall ($300,000 minus $180,000) triggers a 30% initial excise tax ($36,000). When the foundation fails to correct within the taxable period, Section 4942(b) imposes a 100% additional tax on the remaining undistributed amount. Choice D incorrectly states 10% initial and 200% additional — those rates apply to excess benefit transactions under Section 4958, not underdistributions.', 'hard', 4),

-- Q17: medium / L3 — Convenience exclusion applied to university dining
(3, 'Tax-Exempt Organizations', 'Metro University, a 501(c)(3), operates an on-campus dining hall serving meals exclusively to enrolled students and university employees during the academic year. The dining hall generates $450,000 in annual revenue. Determine whether the convenience exclusion applies to exclude this income from UBIT.', '["The convenience exclusion does not apply because the dining hall is a trade or business that is regularly carried on", "The convenience exclusion does not apply because generating $450,000 in revenue demonstrates a clear profit motive", "The convenience exclusion applies because the dining hall is operated primarily for the convenience of students and employees", "The convenience exclusion applies only if all meals are sold at cost with no markup"]'::jsonb, 2, 'Under IRC Section 513(a)(2), activities conducted for the convenience of members, students, patients, or employees are excluded from UBIT even if the activity otherwise meets all three parts of the UBIT test. The dining hall serves exclusively enrolled students and employees, qualifying for this exclusion. Choice A incorrectly ignores the statutory exclusion, which applies regardless of whether the three-part test is met.', 'medium', 3),

-- Q18: easy / L1 — Form 8868 purpose
(3, 'Tax-Exempt Organizations', 'What is the purpose of Form 8868 for a tax-exempt organization?', '["To request an automatic 6-month extension of time to file the annual information return", "To apply for reinstatement of tax-exempt status after automatic revocation", "To elect the Section 501(h) expenditure test for lobbying activities", "To report a change in the organization''s exempt purpose to the IRS"]'::jsonb, 0, 'Form 8868 is used by tax-exempt organizations to request an automatic 6-month extension for filing their annual information return (Form 990, 990-EZ, 990-PF, or 990-T). For calendar-year organizations, this extends the May 15 deadline to November 15. Choice B is incorrect — reinstatement after automatic revocation requires filing Form 1023 or Form 1024, not Form 8868.', 'easy', 1),

-- Q19: medium / L3 — Disqualified person definition scope under Section 4958
(3, 'Tax-Exempt Organizations', 'Beacon Community Foundation, a 501(c)(3) public charity, hires a consulting firm owned by the brother of its executive director. The contract pays $75,000 for strategic planning services at market rates. The board approved the contract without knowing about the family relationship and without following comparability procedures. Determine whether Section 4958 intermediate sanctions could apply.', '["Section 4958 cannot apply because the compensation is at fair market value", "Section 4958 cannot apply because consulting firms cannot be disqualified persons", "Section 4958 applies only if the executive director personally receives a financial benefit from the contract", "Section 4958 could apply because family members of persons with substantial influence are disqualified persons, and the board did not follow rebuttable presumption procedures"]'::jsonb, 3, 'Under IRC Section 4958(f)(1), disqualified persons include family members of those exercising substantial influence over the organization. The executive director''s brother is a disqualified person, and the board''s failure to use comparability data and document its decision means the rebuttable presumption of reasonableness does not apply. Choice A is incorrect because fair market value alone does not prevent Section 4958 scrutiny — procedural safeguards must also be followed.', 'medium', 3),

-- Q20: medium / L2 — 509(a)(1) one-third public support test with 2% cap
(3, 'Tax-Exempt Organizations', 'Maple Grove Cultural Society, a 501(c)(3), has total support of $600,000 over the measuring period: $50,000 from government grants, $50,000 from numerous small public donations, and $500,000 from a single private donor. Does the organization meet the one-third public support test under Section 509(a)(1)?', '["Yes, because total contributions from all sources exceed $500,000", "No, because the single donor''s contribution is capped at $12,000 (2% of $600,000) for the public support test, leaving only $112,000 of qualifying support — below the $200,000 threshold", "Yes, because government grants plus public donations ($100,000) exceed the minimum filing threshold", "No, because organizations receiving more than 50% of support from a single donor are automatically classified as private foundations"]'::jsonb, 1, 'Under IRC Section 509(a)(1), public support must exceed one-third of total support. Contributions from any single donor exceeding 2% of total support are capped at the 2% amount ($12,000). Government grants ($50,000) plus public donations ($50,000) plus the capped private donation ($12,000) equals $112,000 — well below the $200,000 threshold (one-third of $600,000). Choice A incorrectly counts the full $500,000 donation as public support.', 'medium', 2),

-- Q21: medium / L2 — Intermediate sanctions 25% initial tax rate
(3, 'Tax-Exempt Organizations', 'Horizon Youth Services, a 501(c)(4) social welfare organization, pays its program director a $400,000 salary. An independent analysis shows comparable compensation is $250,000. Under Section 4958, what is the initial excise tax on the program director for the $150,000 excess benefit?', '["$15,000, which is 10% of the excess benefit", "$7,500, which is 5% of the excess benefit", "$30,000, which is 20% of the excess benefit", "$37,500, which is 25% of the excess benefit"]'::jsonb, 3, 'Under IRC Section 4958(a)(1), the initial excise tax on a disqualified person who receives an excess benefit is 25% of the excess benefit amount. The excess benefit is $150,000 ($400,000 paid minus $250,000 comparable value), so the initial tax is $37,500. Choice A confuses the 10% rate, which applies to organization managers who knowingly participate in the transaction, not to the disqualified person receiving the benefit.', 'medium', 2),

-- Q22: easy / L1 — Exempt purposes under 501(c)(3)
(3, 'Tax-Exempt Organizations', 'Under IRC Section 501(c)(3), which of the following is a recognized exempt purpose?', '["Educational", "Commercial", "Recreational", "Political"]'::jsonb, 0, 'Under IRC Section 501(c)(3), educational is one of the specifically enumerated exempt purposes, along with religious, charitable, scientific, literary, testing for public safety, fostering amateur sports competition, and prevention of cruelty to children or animals. Choice D is incorrect — political activity is not only excluded as an exempt purpose but is absolutely prohibited for 501(c)(3) organizations.', 'easy', 1),

-- Q23: medium / L2 — Organization manager tax with $20,000 cap under Section 4958
(3, 'Tax-Exempt Organizations', 'Caring Hands Foundation, a 501(c)(3), provides its departing CEO a $600,000 severance payment when comparable severance is $200,000. The board treasurer, who is the CEO''s spouse, knowingly approved the transaction. What excise tax applies to the treasurer under Section 4958?', '["$100,000, which is 25% of the excess benefit", "$80,000, which is 20% of the excess benefit", "$20,000, which is 10% of the excess benefit capped at $20,000 per transaction", "$40,000, which is 10% of the excess benefit with no cap"]'::jsonb, 2, 'Under IRC Section 4958(a)(2), an organization manager who knowingly participates in an excess benefit transaction is subject to a 10% excise tax on the excess benefit, capped at $20,000 per transaction. The excess benefit is $400,000 ($600,000 minus $200,000), and 10% equals $40,000, but the statutory cap limits the manager''s tax to $20,000. Choice D incorrectly ignores the $20,000 per-transaction cap established in Section 4958(d)(2).', 'medium', 2),

-- Q24: medium / L2 — Section 509(a)(2) gross receipts qualification path
(3, 'Tax-Exempt Organizations', 'Bright Minds After-School Program, a 501(c)(3), receives $200,000 from tuition for educational programs, $50,000 from government grants, $30,000 from individual donations, and $120,000 from investment dividends. Total support is $400,000. Under Section 509(a)(2), does the organization qualify as a public charity?', '["No, because the $120,000 in investment dividends exceeds one-third of total support", "Yes, because qualifying support ($280,000) exceeds one-third of total support and investment income ($120,000) does not exceed one-third", "No, because tuition fees cannot count as qualifying support under Section 509(a)(2)", "Yes, but only if the organization also passes the Section 509(a)(1) public support test"]'::jsonb, 1, 'Under IRC Section 509(a)(2), an organization qualifies as a public charity if more than one-third of support comes from contributions, membership fees, and gross receipts from exempt-function activities, and not more than one-third from gross investment income. Qualifying support ($280,000) is 70% of total support, and investment income ($120,000) is 30% — satisfying both prongs. Choice A incorrectly states that 30% exceeds one-third (33.3%).', 'medium', 2),

-- Q25: medium / L3 — Failure to file penalty computation
(3, 'Tax-Exempt Organizations', 'Heritage Preservation Society, a small 501(c)(3) with gross receipts of $150,000, files its Form 990-EZ 60 days late without reasonable cause. Calculate the penalty under Section 6652(c).', '["$1,000, because there is a flat $1,000 penalty for any late filing", "$3,000, calculated at $50 per day for 60 days", "$1,200, calculated at $20 per day for 60 days, subject to a maximum of the lesser of $10,500 or 5% of gross receipts", "$7,500, which is 5% of gross receipts applied as a flat penalty"]'::jsonb, 2, 'Under IRC Section 6652(c)(1)(A), the penalty for late filing of Form 990 or 990-EZ is $20 per day for each day the return is late, up to the lesser of $10,500 or 5% of gross receipts (for organizations with gross receipts under $1,186,000). At $20 per day for 60 days, the penalty is $1,200, which is within both caps ($10,500 and $7,500). Choice D incorrectly applies 5% of gross receipts as a flat penalty rather than the per-day calculation.', 'medium', 3),

-- Q26: hard / L4 — Expenditure responsibility for grants to non-charities
(3, 'Tax-Exempt Organizations', 'Atlas Education Foundation, a private foundation, makes a $100,000 grant to a 501(c)(4) social welfare organization for a community literacy program. The foundation''s attorney advises that the grant does not require expenditure responsibility because the recipient has tax-exempt status. Evaluate whether this legal advice is correct under Section 4945.', '["The advice is correct — grants to any tax-exempt organization are excluded from Section 4945''s taxable expenditure rules", "The advice is correct — expenditure responsibility is only required for grants to foreign organizations, not domestic tax-exempt entities", "The advice is partially correct — the foundation must file Form 4720 but need not exercise expenditure responsibility", "The advice is incorrect — grants to non-501(c)(3) organizations require expenditure responsibility under Section 4945(d)(4), including a pre-grant inquiry, written agreement, and annual reporting"]'::jsonb, 3, 'Under IRC Section 4945(d)(4) and (h), grants by a private foundation to organizations other than 501(c)(3) public charities are taxable expenditures unless the foundation exercises expenditure responsibility. A 501(c)(4) is not a 501(c)(3), so the foundation must conduct a pre-grant inquiry, obtain a written agreement restricting funds to charitable purposes, and report annually on Form 990-PF. Choice A incorrectly equates all tax-exempt organizations; the rule distinguishes 501(c)(3) recipients from other exempt entities.', 'hard', 4),

-- Q27: hard / L4 — Section 4940 net investment income computation
(3, 'Tax-Exempt Organizations', 'Pemberton Arts Foundation, a private foundation, reports the following 2026 income: $100,000 in dividends, $50,000 in interest, $50,000 in net long-term capital gains from selling appreciated securities, and $20,000 in expenses directly connected to investment activities. Calculate the Section 4940 excise tax on net investment income.', '["$2,502, computed as 1.39% of net investment income of $180,000", "$2,700, computed as 1.5% of net investment income of $180,000", "$2,090, computed as 1.39% of $150,000 because capital gains are excluded from net investment income", "$3,600, computed as 2% of net investment income of $180,000"]'::jsonb, 0, 'Under IRC Section 4940(a) and (c), private foundations pay a 1.39% excise tax on net investment income, which includes gross investment income (dividends, interest, rents, royalties) plus net capital gains, minus directly connected expenses. Net investment income is $100,000 + $50,000 + $50,000 minus $20,000 = $180,000. The tax is 1.39% times $180,000 = $2,502. Choice C incorrectly excludes capital gains; Section 4940(c)(4) explicitly includes net capital gains.', 'hard', 4),

-- Q28: medium / L2 — Incidental personal property rule (under 10% threshold)
(3, 'Tax-Exempt Organizations', 'Westfield Historical Society, a 501(c)(3), leases a historic building to a restaurant under a single lease. Total annual rent is $60,000, with $5,000 allocated to tables and kitchen equipment (personal property) and $55,000 to the building (real property). How is this rental income treated for UBIT purposes?', '["The entire $60,000 is subject to UBIT because any inclusion of personal property taints the entire lease", "The entire $60,000 is excluded from UBIT because the personal property portion ($5,000) is less than 10% of total rent and is therefore incidental", "Only the $5,000 personal property portion is subject to UBIT while the $55,000 real property rent is excluded", "The entire $60,000 is excluded because all rental income from historic properties is exempt"]'::jsonb, 1, 'Under IRC Section 512(b)(3), rents from real property are excluded from UBIT. When a lease includes both real and personal property, the personal property rent is disregarded if incidental — defined as 10% or less of total rents. Here, personal property rent ($5,000) is 8.3% of total rent ($60,000), below the 10% threshold, so the entire $60,000 is excluded. Choice C incorrectly splits the income; the 10% incidental test determines treatment of the entire lease amount.', 'medium', 2),

-- Q29: easy / L1 — Section 4941 initial tax rate on self-dealer
(3, 'Tax-Exempt Organizations', 'Under Section 4941, what is the initial excise tax rate imposed on a disqualified person who engages in self-dealing with a private foundation?', '["5%", "20%", "10%", "25%"]'::jsonb, 2, 'Under IRC Section 4941(a)(1), the initial excise tax on a disqualified person who engages in an act of self-dealing with a private foundation is 10% of the amount involved for each year in the taxable period. Choice D is incorrect — 25% is the initial excise tax rate under Section 4958 for excess benefit transactions involving public charities and 501(c)(4) organizations, not private foundation self-dealing.', 'easy', 1),

-- Q30: easy / L1 — Operational test primary requirement
(3, 'Tax-Exempt Organizations', 'What does the operational test require for a Section 501(c)(3) organization?', '["The organization must be operated primarily for one or more exempt purposes", "The organization must generate at least 51% of its revenue from donations", "The organization must have at least three unrelated board members", "The organization must distribute all net income annually to beneficiaries"]'::jsonb, 0, 'Under IRC Section 501(c)(3) and Reg. 1.501(c)(3)-1(c), the operational test requires that an organization be operated primarily for exempt purposes, meaning its activities must primarily accomplish its stated exempt goals. Choice D is incorrect — the operational test does not require annual distribution of all income; that requirement applies only to private foundations under Section 4942 (5% minimum distribution).', 'easy', 1)
;

COMMIT;
